 ys,xs=np.where(mask);print('\n',c,'n',len(xs),'bbox',(xs.min(),xs.max(),ys.min(),ys.max()) if len(xs) else None,'pxmedian',(np.median(xs),np.median(ys)) if len(xs) else None)
