 if pts:print('world median',np.round(np.median(pts,axis=0),3),'p10-90',np.round(np.percentile(pts,[10,90],axis=0),3))
 for u,w in [(120,170),(125,175),(130,180),(120,185)]:
  if c=='robot0_eye_in_right_hand':
   z=float(d[w,u]);cam=np.array([(u-K[0,2])/K[0,0]*z,-(w-K[1,2])/K[1,1]*z,-z,1]);print('pix',u,w,im[w,u],round(z,3),np.round((M@cam)[:3],3))
